# Pandas rows for the Python reference page (genref.py adds them as their own section). Every example is run by genref.py.
D = 'import pandas as pd\ndf = pd.DataFrame({"name": ["Asha", "Ravi", "Neha"], "dept": ["IT", "HR", "IT"], "pay": [72000, 45000, 58000]})\n'
S = 'import pandas as pd\ns = pd.Series([30, None, 10, 20])\n'
PANDAS = [
  ("pd.read_csv(path)", "Reads a CSV file into a DataFrame", D + 'df.to_csv("staff.csv", index=False)\nprint(pd.read_csv("staff.csv").shape)'),
  ("pd.read_excel(path, sheet_name)", "Reads one sheet of an Excel file (needs openpyxl)", None, "On your laptop: `pip install openpyxl` once. See Chapter 23."),
  ("df.to_csv(path, index=False)", "Saves the table as a CSV file, without the index column", D + 'df.to_csv("staff.csv", index=False)\nprint(open("staff.csv").readline().strip())'),
  ("df.head(n) / df.tail(n)", "The first / last n rows (5 if you give no number)", D + 'print(df.head(1)["name"].tolist(), df.tail(1)["name"].tolist())'),
  ("df.sample(n, random_state)", "n random rows; random_state makes them repeat", D + 'print(len(df.sample(2, random_state=1)))'),
  ("df.shape", "(rows, columns), a value, not a method", D + 'print(df.shape)'),
  ("df.info()", "Each column's type and number of filled values", D + 'df.info(memory_usage=False)'),
  ("df.describe()", "count, mean, std, min, quartiles and max of number columns", D + 'print(round(df["pay"].describe()["mean"], 1))'),
  ("s.isna() / s.notna()", "True where a value is missing / filled", S + 'print(s.isna().sum(), s.notna().sum())'),
  ("df.duplicated()", "True for every row that repeats an earlier one", 'import pandas as pd\nd = pd.DataFrame({"id": [1, 1, 2]})\nprint(d.duplicated().tolist())'),
  ("df.drop_duplicates(subset)", "Removes repeated rows (or repeats in some columns)", 'import pandas as pd\nd = pd.DataFrame({"id": [1, 1, 2]})\nprint(len(d.drop_duplicates()))'),
  ("s.dropna() / df.dropna(subset)", "Removes values or rows with gaps", S + 'print(s.dropna().tolist())'),
  ("s.fillna(value)", "Fills the gaps with a value, mean, median or mode()[0]", S + 'print(s.fillna(s.mean()).tolist())'),
  ("s.ffill() / s.bfill()", "Fills a gap with the value above / below it", S + 'print(s.ffill().tolist())'),
  ("df.drop(columns=[...], index=[...])", "Removes columns or rows by name", D + 'print(list(df.drop(columns=["pay"]).columns))'),
  ("s.astype(type)", "Changes the type of a column", 'import pandas as pd\nprint(pd.Series(["5", "7"]).astype("int64").sum())'),
  ("pd.to_numeric(s, errors='coerce')", "Text to numbers; bad values become NaN", 'import pandas as pd\nprint(pd.to_numeric(pd.Series(["5", "x"]), errors="coerce").tolist())'),
  ("s.str.strip() / .lower() / .title()", "String methods on every value of a text column", 'import pandas as pd\nprint(pd.Series([" asha RAO "]).str.strip().str.title().tolist())'),
  ("s.str.replace(a, b, regex=False)", "Swaps text in every value", 'import pandas as pd\nprint(pd.Series(["₹1,200"]).str.replace(",", "", regex=False).tolist())'),
  ("s.str.split(sep, expand=True)", "Splits text into several columns", 'import pandas as pd\nprint(pd.Series(["Asha Rao"]).str.split(" ", expand=True).shape)'),
  ("s.str.contains(x) / s.str.extract(r'(...)')", "True if x is inside / the part of the text in brackets", 'import pandas as pd\ne = pd.Series(["asha@gmail.com"])\nprint(e.str.contains("gmail").tolist(), e.str.extract(r"@(.+)", expand=False).tolist())'),
  ("s.map(dict) / s.replace(dict)", "Translate every value (others NaN) / fix some values", 'import pandas as pd\nc = pd.Series(["It", "Sales"])\nprint(c.map({"It": "IT"}).tolist(), c.replace({"It": "IT"}).tolist())'),
  ("pd.to_datetime(s, format='mixed', dayfirst=True, errors='coerce')", "Text to real dates; bad values become NaT", 'import pandas as pd\nprint(pd.to_datetime(pd.Series(["03/04/2025"]), dayfirst=True).dt.month.tolist())'),
  ("s.dt.year / .month / .day_name() / .strftime(fmt)", "Parts of a date column", 'import pandas as pd\nd = pd.to_datetime(pd.Series(["2025-08-15"]))\nprint(d.dt.year[0], d.dt.day_name()[0], d.dt.strftime("%d-%b")[0])'),
  ("df.loc[rows, cols]", "Picks by labels and names; a slice includes its end", D + 'print(df.loc[0:1, "name"].tolist())'),
  ("df.iloc[rows, cols]", "Picks by positions; a slice leaves out its end", D + 'print(df.iloc[0:1, 0].tolist())'),
  ("df[condition]", "Keeps the rows where the condition is True (& | ~ with brackets)", D + 'print(df[(df["dept"] == "IT") & (df["pay"] > 60000)]["name"].tolist())'),
  ("df.query('...')", "A filter written like a sentence; @name uses a variable", D + 'print(df.query("pay < 60000")["name"].tolist())'),
  ("s.isin(list) / s.between(a, b)", "True if the value is in the list / in the range (ends included)", D + 'print(df["pay"].between(45000, 60000).tolist())'),
  ("s.apply(func) / df.apply(func, axis=1)", "Runs your function on every value / every row", D + 'print(df["pay"].apply(lambda x: x // 1000).tolist())'),
  ("df.sort_values(by, ascending)", "Sorts the rows by one or more columns", D + 'print(df.sort_values("pay", ascending=False)["name"].tolist())'),
  ("s.value_counts(normalize)", "How many of each value (or shares with normalize=True)", D + 'print(df["dept"].value_counts().tolist())'),
  ("s.unique() / s.nunique()", "The different values / how many there are", D + 'print(df["dept"].unique().tolist(), df["dept"].nunique())'),
  ("s.idxmax() / s.idxmin()", "The index label of the largest / smallest value", D + 'print(df.loc[df["pay"].idxmax(), "name"])'),
  ("df.groupby(col)[col2].agg(...)", "Summaries per group: mean, sum, count, named aggregation", D + 'print(df.groupby("dept")["pay"].sum().tolist())'),
  ("groupby(...).transform(func)", "The group's result on every row", D + 'print(df.groupby("dept")["pay"].transform("max").tolist())'),
  ("df.pivot_table(values, index, columns, aggfunc, fill_value)", "An Excel-style pivot table", D + 'print(df.pivot_table(values="pay", index="dept", aggfunc="count")["pay"].tolist())'),
  ("pd.cut(s, bins, labels)", "Puts numbers into ranges (bands)", 'import pandas as pd\nprint(pd.cut(pd.Series([15, 55]), bins=[0, 50, 100], labels=["Low", "High"]).tolist())'),
  ("pd.merge(a, b, on, how)", "Joins two tables side by side: inner, left, right or outer", D + 'h = pd.DataFrame({"dept": ["IT"], "head": ["Om"]})\nprint(len(pd.merge(df, h, on="dept", how="left")))'),
  ("pd.concat([a, b], ignore_index=True)", "Stacks tables on top of each other", D + 'print(len(pd.concat([df, df], ignore_index=True)))'),
  ("s.corr(other) / df.corr()", "Correlation from -1 to 1", 'import pandas as pd\nd = pd.DataFrame({"x": [1, 2, 3], "y": [2, 4, 7]})\nprint(round(d["x"].corr(d["y"]), 2))'),
  ("df.reset_index(drop)", "Turns the index into a column, or renumbers the rows 0, 1, 2", D + 'print(df.groupby("dept")["pay"].sum().reset_index().columns.tolist())'),
  ("df.set_index(col)", "Uses a column as the row labels", D + 'print(df.set_index("name").loc["Ravi", "pay"])'),
]
